import hashlib
import hmac
import time
import threading
import json
from functools import lru_cache
from dataclasses import dataclass, field
from typing import Dict, Set, Optional

# Configuration
SESSION_TIMEOUT = 3600
MAX_SESSIONS = 10000

@dataclass
class Permission:
    roles: Set[str] = field(default_factory=set)
    resources: Dict[str, Set[str]] = field(default_factory=dict)
    cached_at: float = 0.0

    def has_access(self, resource: str, action: str) -> bool:
        if 'admin' in self.roles:
            return True
        actions = self.resources.get(resource, set())
        return action in actions

    def grant_temporary_access(self, resource: str, action: str):
        """Grant temporary access for the current request context."""
        if resource not in self.resources:
            self.resources[resource] = set()
        self.resources[resource].add(action)


class PermissionStore:
    """Simulates loading permissions from a database."""

    _base_permissions = {
        'user': Permission(
            roles={'user'},
            resources={'profile': {'read', 'write'}, 'posts': {'read', 'create'}}
        ),
        'moderator': Permission(
            roles={'moderator'},
            resources={'profile': {'read', 'write'}, 'posts': {'read', 'create', 'delete'}, 'reports': {'read'}}
        ),
        'admin': Permission(
            roles={'admin'},
            resources={'profile': {'read', 'write'}, 'posts': {'read', 'create', 'delete'}, 'admin_panel': {'read', 'write'}}
        ),
    }

    @staticmethod
    @lru_cache(maxsize=256)
    def get_permissions(role: str) -> Optional[Permission]:
        """Get permissions for a role. Cached for performance.

        Note: Returns cached Permission object for efficiency.
        Callers should not modify the returned object.
        """
        base = PermissionStore._base_permissions.get(role)
        if base is None:
            return None
        # Return the permission object (cached after first call)
        return Permission(
            roles=set(base.roles),
            resources={k: set(v) for k, v in base.resources.items()},
            cached_at=time.time()
        )


class SessionManager:
    def __init__(self, secret_key: str):
        self._secret = secret_key.encode('utf-8')
        self._sessions: Dict[str, dict] = {}
        self._lock = threading.RLock()

    def create_session(self, user_id: str, role: str) -> str:
        token = self._generate_token(user_id)
        with self._lock:
            self._sessions[token] = {
                'user_id': user_id,
                'role': role,
                'created_at': time.time()
            }
        return token

    def get_session(self, token: str) -> Optional[dict]:
        with self._lock:
            session = self._sessions.get(token)
            if session is None:
                return None
            if time.time() - session['created_at'] > SESSION_TIMEOUT:
                del self._sessions[token]
                return None
            return session

    def _generate_token(self, user_id: str) -> str:
        payload = f"{user_id}:{time.time()}:{threading.current_thread().ident}"
        return hmac.new(self._secret, payload.encode(), hashlib.sha256).hexdigest()


class AccessController:
    """Main access control system."""

    def __init__(self, session_manager: SessionManager):
        self._session_mgr = session_manager
        self._audit_log = []
        self._log_lock = threading.Lock()

    def check_access(self, token: str, resource: str, action: str, 
                     context: Optional[Dict] = None) -> bool:
        """Check if a session token has access to perform action on resource."""
        session = self._session_mgr.get_session(token)
        if session is None:
            return False

        role = session['role']
        permissions = PermissionStore.get_permissions(role)
        if permissions is None:
            return False

        # Apply context-based temporary permissions
        if context and 'temporary_grants' in context:
            for grant in context['temporary_grants']:
                grant_resource = grant.get('resource', '')
                grant_action = grant.get('action', '')
                if grant_resource and grant_action:
                    # Grant temporary access on the permission object
                    permissions.grant_temporary_access(grant_resource, grant_action)

        result = permissions.has_access(resource, action)

        self._log_access(session['user_id'], resource, action, result)
        return result

    def _log_access(self, user_id: str, resource: str, action: str, granted: bool):
        with self._log_lock:
            self._audit_log.append({
                'user_id': user_id,
                'resource': resource,
                'action': action,
                'granted': granted,
                'timestamp': time.time()
            })


def create_app(secret_key: str) -> AccessController:
    """Factory function to create the access control system."""
    session_mgr = SessionManager(secret_key)
    return AccessController(session_mgr)


# Request handler simulation
def handle_request(controller: AccessController, token: str, 
                   resource: str, action: str, request_body: Optional[str] = None):
    """Simulate handling an HTTP request with access control."""
    context = None
    if request_body:
        try:
            body = json.loads(request_body)
            context = body.get('context')
        except (json.JSONDecodeError, AttributeError):
            pass

    if controller.check_access(token, resource, action, context):
        return {'status': 200, 'message': f'Access granted to {action} on {resource}'}
    else:
        return {'status': 403, 'message': 'Access denied'}
